        "【第 1 步：審題定位 · 題眼與已知】本題橫跨八年級構圖形式原理（對稱平衡 vs 三分法則非對稱平衡）與跨文化空間再現觀（文藝復興單點線性透視 vs 傳統山水散點透視 vs 立體派多視角平面重組）。題眼在於檢驗能否破除「單一寫實標準中心主義」。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據視E-IV-2 核心素養與課綱防誤導指引：① 線性透視假設觀者「單眼固定不動於一點觀看」，適合科學光學寫實，但絕非所有藝術必須服從的唯一鐵律；② 東方水墨「散點透視（三遠：高遠、深遠、平遠）」追求人在自然中游目周覽的整體生命經驗；③ 立體派（Cubism）刻意打破文藝復興以來的單一視點幻覺，納入時間與多角度觀察；④ 構圖平衡包含「對稱平衡（莊重嚴謹）」與「非對稱平衡（配合三分法則交點，藉面積、明暗、動勢達成生動均衡）」。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 對照展件 I、II、III 的空間邏輯：拉斐爾以固定單點透視強化理性秩序；宋代畫家以移動視點突破單一取景框限制；畢卡索則主動解構三維透視幻覺，展現二十世紀現代藝術的多維度造形探索。三者皆高度契合其時代精神與創作意圖。\n2. 對照構圖平衡：紀實攝影將主體老樹置於井字三分線交點，並以右上方雲霞飛鳥呼應配重，正是經典的「三分法則＋非對稱動態平衡」。\n3. 綜合上述分析，選項 (A) 完整呈現多元藝術空間觀且不偏頗，為正確解答。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：犯了將西方單一光學透視奉為唯一優劣尺度的文化偏見，忽略長卷山水「可行、可望、可游、可居」的主動多視點美學設計。\n• 選項 (C) 錯誤：誤以為「平衡（Balance）」等於「完全對稱（Symmetry）」；非對稱平衡透過視覺重量槓桿原理（如小而深色的老樹平衡大而輕淺的雲霞）反而更具韻律感。\n• 選項 (D) 錯誤：立體派正側臉並置是「打破並反叛傳統線性透視與相機瞬間單一視角」，絕非兩點建築透視製圖。",
        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒、翰林、奇鼎三版在透視單元結尾皆設有「打破透視的藝術家」延伸專欄（常舉北宋郭熙／張擇端、畢卡索或艾雪 M. C. Escher 錯視版畫為例）：記住「透視是工具而非枷鎖，寫實是風格而非唯一標準」，即可秒解跨文化賞析題。"
