        "【第 1 步：審題定位 · 題眼與已知】題幹呈現一件結合廢棄漁網與燈光投影的當代環境裝置藝術，以及小安、小柏、小澄、小岱四段不同層次的觀展文字。題眼在於精準對應「描述→形式分析→詮釋→判斷」四步驟，並識破以個人好惡或單一古典標準全盤否定作品的迷思。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱視覺藝術鑑賞與文化理解（視P-IV-2、視3-IV-2）：① 描述（Description）：客觀陳述尺寸、媒材與可見物象；② 形式分析（Analysis）：剖析構圖、空間高低、肌理與光影對比如何營造視覺感受；③ 詮釋（Interpretation）：串聯形式線索與創作者社會環境脈絡，提出合理意義推論；④ 判斷（Judgment）：綜合美學形式與社會文化意義提出具證據的評價，絕非單憑「我不喜歡」或單一繪畫傳統定生死。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 定位小安筆記：具體列出「4×6 公尺、廢棄漁網、塑膠浮球、鏽蝕鐵鉤、深藍水波投影」，純粹客觀盤點事實，屬「描述」。\n2. 定位小柏筆記：剖析「漏斗狀非對稱構圖重心、暗黑粗糙肌理 vs 冷藍光影、仰視包圍張力」，探討形式如何產生效果，屬「形式分析」。\n3. 定位小澄筆記：結合「東海岸淨灘脈絡」解讀巨網籠罩觀者的生態警世隱喻，有視覺證據支撐，屬「詮釋」。\n4. 診斷小岱筆記：以「只接受漂亮古典油畫」的單一尺度排斥當代裝置媒材，並把「我不喜歡」當成否定一切價值的結論，缺乏形式與文化脈絡論證。故正確選項為 (D)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：小安僅記錄肉眼可見的材質、數量與尺寸，完全不含主觀褒貶，屬於第一階段「客觀描述」而非價值判斷。\n• 選項 (B) 錯誤：小柏明確分析了「非對稱構圖重心、觸覺肌理、冷色光影包圍感」，全屬標準視覺形式分析。\n• 選項 (C) 錯誤：個人直覺喜惡可以作為觀展起點，但若拒絕理解作品脈絡、拿古典花卉油畫規則硬套當代環境裝置，便落入單一文化媒材偏見，絕非客觀詮釋。",
