        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：若每段都換成毫無關聯的新曲調，那叫「組曲或串燒（A-B-C-D）」，而非围绕同一核心演化的「變奏曲（A-A1-A2...）」。\n• 選項 (C) 錯誤：大調轉小調會直接將明亮溫暖的和聲色彩轉為憂鬱緊張，搭配 ff 強音更具強烈戲劇衝擊，與換座位無關。\n• 選項 (D) 錯誤：室內樂重奏人數只算實際演奏獨立聲部的音樂家（通常不設專職指揮），《鱒魚五重奏》是「鋼琴＋小提琴＋中提琴＋大提琴＋低音提琴」共五件樂器。",
