      "stem": "七年級班級戲劇公演在學校禮堂標準「鏡框式舞臺」進行走位排練。開場時，飾演偵探的阿凱站在「舞臺正中央（C，Center Stage）」，正面朝向台下觀眾席。導演喊出以下兩段連續走位指令：\n• 指令一：「阿凱，請從正中央往『左上舞臺（UL，Upstage Left）』後退移動，去檢查後方的書櫃道具！」\n• 指令二：「接著發現線索後，請斜向大步穿過全場，直接走到『右下舞臺（DR，Downstage Right）』停住，靠近觀眾低聲說出關鍵推理！」\n若你是坐在台下觀眾席正中間的評審老師，看著舞臺畫面，請問阿凱在執行「指令一」與「指令二」時，分別移動到你眼前舞臺畫面的哪兩個位置？",
