        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 檢核剛性限制條件：\n   • 方案甲：成本 110 元（≦ 120 元）、寬度 30 cm（介於 28～32 cm）→ 符合限制條件。\n   • 方案乙：成本 135 元（＞ 120 元，超支 15 元）→ 違反成本限制，淘汰。\n   • 方案丙：成本 95 元（≦ 120 元）、寬度 29 cm（介於 28～32 cm）→ 符合限制條件。\n   • 方案丁：寬度 35 cm（＞ 32 cm，塞不進標準書櫃）→ 違反尺寸限制，淘汰。\n2. 計算合規方案（甲、丙）之決策矩陣加權總分：\n   • 方案甲加權總分 ＝ 8 × 0.5 ＋ 7 × 0.3 ＋ 9 × 0.2 ＝ 4.0 ＋ 2.1 ＋ 1.8 ＝ 7.9 分。\n   • 方案丙加權總分 ＝ 9 × 0.5 ＋ 9 × 0.3 ＋ 6 × 0.2 ＝ 4.5 ＋ 2.7 ＋ 1.2 ＝ 8.4 分。\n3. 比較結果：8.4 分 ＞ 7.9 分，方案丙兼具符合規範與最高加權效益，故正確選項為 (C)。",
