        "requiredKnowledge": "回推必備知識：四邊形鉸接框架受側向剪力易變形為平行四邊形，唯有三角形三邊長固定時內角唯一（幾何穩固性），是桁架橋與鐵塔的基本單元；橋面中央受向下重壓時會微幅下凹，使橋體『上部受壓力、下部受張力』。材料選擇須權衡強度、硬度、韌性（抗衝擊不斷裂能力）、密度重量與加工性：例如高硬度陶瓷或脆性薄玻璃韌性極低易碎；木材順紋抗拉與抗彎強度遠優於橫紋；熱塑性塑膠加熱軟化可塑形回收，熱固性塑膠受熱固化後不再軟化耐熱佳。",
