        "【第 1 步：審題定位 · 題眼與已知】已知三枚單純外接齒輪 A（15 齒，主動輪，360 rpm，順時針）→ 惰輪 B（30 齒）→ 從動輪 C（45 齒）。題眼在於同時判定 C 輪的「順／逆時針轉向」、「精確轉速 rpm」以及「減速增扭（省力）」特性。",
        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱機構傳動原理（生A-IV-2）：① 兩外接齒輪轉向必相反；② 齒數與轉速成反比（N_A × n_A ＝ N_B × n_B ＝ N_C × n_C），中間惰輪 B 只改變轉向而不影響首末輪總轉速比；③ 在輸入功率固定下，轉速減慢則輸出扭力成比例放大（省力費時），適合吊起重物。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 判定旋轉方向：主動輪 A 為「順時針」→ 外接惰輪 B 必為「逆時針」→ 再外接從動輪 C 必反轉回「順時針」（與主動輪 A 同向）。\n2. 分步與直接計算從動輪 C 轉速：\n   • 先算惰輪 B 轉速：n_B ＝ 360 × (15 ÷ 30) ＝ 180 rpm。\n   • 再算從動輪 C 轉速：n_C ＝ 180 × (30 ÷ 45) ＝ 120 rpm（亦可直接由首末輪公式算得：360 × 15 ÷ 45 ＝ 120 rpm）。\n3. 判定力學功能特性：小齒輪（15 齒）經惰輪帶動大齒輪（45 齒），轉速降為原本的 1/3（減速），輸出軸扭力則提升為原本的 3 倍（放大扭力、省力吊重），故正確選項為 (A)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (B) 錯誤：漏算惰輪 B 造成的第二次反向（A 順→B 逆→C 順），誤判 C 為逆時針，且將減速傳動的扭力變化說反為費力。\n• 選項 (C) 錯誤：將齒數與轉速誤當成正比（360 × 45 ÷ 15 ＝ 1,080 rpm），且違反能量守恆（不可能同時加速又放大扭力）。\n• 選項 (D) 錯誤：算到中間惰輪 B 的轉速 180 rpm 就停筆，誤以為惰輪齒數會鎖定最終轉速，忘記繼續換算 B 到 C 的 30：45 齒數比。",
