      "stem": "八年級進行「輕量化人行景觀橋模型」結構與選材實驗。圖表紀錄比較兩種橋身側面構型與三種候選桿件材料：\n• 構型 I：僅以水平橫梁與垂直立柱釘接成連續「四邊形矩形框格」（無對角斜撐）；\n• 構型 II：在矩形框格內加裝對角斜撐桿，分割成連續「三角形桁架單元」；\n• 材料特性實測表：\n  - 材料甲（薄脆高硬度玻璃棒）：表面硬度極高、抗刮，但韌性極低（受輕微彎曲或衝擊即瞬間碎裂），密度 2.5 g/cm³；\n  - 材料乙（松木板材）：具明顯平行木紋，順紋抗拉與抗彎強度遠高於橫紋（逆紋易沿纖維劈裂），密度 0.5 g/cm³；\n  - 材料丙（熱固性美耐皿樹脂塊）：成型硬化後再次加熱也不會軟化重塑，脆性較高且難以熱彎加工。\n當重物靜置於「構型 II 桁架橋」橋面中央正上方，使橋體產生極微小向下彎曲趨勢時，下列關於結構受力與選材加工的判斷，何者正確？",
