        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據生A-IV-2 與生P-IV-5：① 三角形三邊長固定時形狀唯一，抗形變能力遠勝易歪斜成平行四邊形的四邊形；② 梁或桁架受向下重物作用微呈「微笑下凹曲線（∪ 形）」時，內圈（上方頂部）被擠壓縮短承受「壓力（Compression）」，外圈（下方底部）被拉扯伸長承受「張力（Tension）」；③ 選材不可迷信高硬度，承受彎矩與震動必須具備足夠「韌性」，且木材裁切長梁須採「順紋」方向。",
