        "【第 5 步：版本對照 · 跨版本教材提點與大考心法】康軒版常用「拿一塊海綿或橡皮擦往下壓彎」直觀示範：海綿上方皺縮代表受「壓力」、下方裂縫張開代表受「張力」（口訣：下凹上壓下拉）！木材加工牢記「順紋鋸切抗拉強，橫紋受折易斷裂」。"
