      "title": "【機電控制核心判讀】校園智慧農園：定時開迴路與土壤感測閉迴路澆灌系統比較",
      "stem": "九年級生活科技專題改造校園小田園的自動澆水設施，比較前後兩代控制系統架構：\n• 第一代系統（甲）：在微控制器寫入固定排程「每天 07:00 與 17:00 準時通電開啟電磁水閥 180 秒」，管線末端直接噴水，未安裝任何環境偵測元件。\n• 第二代系統（乙）：在作物根部土壤埋設「電容式土壤溼度感測器」連接微控制器輸入端；程式設定當感測器回傳土壤含水率低於 35% 時啟動抽水馬達澆水，並每秒持續讀取土壤含水率變化，一旦含水率回升達 65% 即自動切斷馬達電源停止澆水。\n關於甲、乙兩套控制系統的原理與運作表現，下列分析何者正確？",
