        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱機電整合與自動控制（生A-IV-4）：區分開迴路（Open-loop）與閉迴路（Closed-loop）的唯一關鍵在於「有無回授（Feedback）機制」——即系統輸出結果（實際土壤含水率）是否被感測器量測並傳回控制器與目標值比對修正，而非看有沒有用到微電腦晶片！",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 剖析第一代系統（甲）：控制流程為「時間設定 → 微控制器計時 → 電磁水閥開啟 180 秒 → 土壤溼度改變」，末端土壤究竟乾旱或已淹水並不會回傳給控制器，故屬於「開迴路控制」。若遇梅雨季土壤早已飽和，甲仍機械式噴水 180 秒，導致浪費水資源與爛根。\n2. 剖析第二代系統（乙）：具備「土壤溼度感測器」形成封閉回授迴路，將澆水後的即時含水率回傳與上限值 65% 比對，達標即停、晴天蒸發快則自動補水，屬於典型的「閉迴路控制」，故正確選項為 (B)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：掉入「只要有微控制器／電腦程式就是閉迴路」的常見陷阱；微控制器只跑單向計時器而無感測回授時，依然是開迴路控制。\n• 選項 (C) 錯誤：將乙誤判為開迴路，且忽略 IPO（輸入→處理→輸出）架構中，感測器訊號必須送入微控制器與閾值（35%、65%）運算比對後才驅動馬達。\n• 選項 (D) 錯誤：開迴路構造才最簡單便宜；閉迴路成本較高，且一旦回授感測器損壞或讀值失真（例如感測探針脫落懸空誤測為 0%），反而可能導致馬達不停抽水，需做好感測器維護。",
