        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 檢驗甲、乙、丙之危險誤區：甲未檢點溼滑地面且冷肌肉直接爆發跳躍，極易滑倒扭傷或拉傷；乙重複錯誤動作只會固化錯誤肌肉記憶，且硬撐關節刺痛會引發肌腱炎或韌帶撕裂；丙在劇烈跑後心輸出量極大時突然蹲下不動，血液大量滯留於擴張的下肢血管，回心血量驟減會引發腦部缺氧頭暈、臉色蒼白甚至昏厥（重力性休克）。\n2. 確認丁之科學做法：丁完整實踐「場地檢查→動態暖身→漸進分段練習與回饋修正→傾聽身體刺痛警訊停損→慢走緩和與靜態伸展」，完全符合運動科學與安全原則，故選 (D)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：動態暖身能喚醒神經肌肉協調並降低黏滯阻力，反而能提升運動表現並大幅減少拉傷；場地積水則是滑倒骨折頭號殺手。\n• 選項 (B) 錯誤：把運動後隔天的輕微「延遲性肌肉痠痛（DOMS）」與運動當下的「急性關節韌帶尖銳刺痛」混為一談，更誤將疼痛當成進步必要條件。\n• 選項 (C) 錯誤：劇烈運動後急停蹲坐非但不能加速恢復，反而阻斷靜脈回流引發眩暈昏倒，必須慢走 3～5 分鐘讓心率平緩下降後再伸展。",
