        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱定向與環境觀察核心（童Ca-IV-1、童Ca-IV-2）：① 指北針磁針依靠地球微弱磁場運作，極易受近距離鐵器、磁鐵、手機喇叭／磁吸殼及高壓電線干擾偏轉，且必須水平放置避免卡針；②「正置地圖（地圖歸北）」是轉動地圖使「圖北」配合「磁針北」，使地圖方位與真實世界一致；③ 電子設備在山區易遇低溫耗電關機、峽谷訊號反射飄移或摔機故障，自然植物線索亦受局部微氣候干擾，皆須「圖、針、實地地標」三方互證。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 檢視小安的操作：遠離鐵哨、鋼欄杆、高壓電與手機磁鐵→確保磁針真實指向地磁北方；水平轉動整張地圖讓地圖北方指標對齊磁針紅端→正確完成正置地圖；最後抬頭對照岔路山頭地標→落實圖地對應。\n2. 檢視小柏、小岑、小迪的缺失：小柏受鐵桌與磁吸殼強烈磁場干擾導致磁針亂指，且未讓磁針與刻度 N、圖北重合；小岑陷入「只盯電子工具不看環境」陷阱；小迪忽略臺灣森林高濕多霧、溪谷水氣與林冠透光皆會讓樹幹四面長青苔。因此最正確者為小安，故正確選項為 (A)。",
