        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱環境倫理與無痕山林準則（童Da-IV-2）：LNT 核心鐵律包含：在可承受地點行走宿營（不切西瓜破壞植披導致水土流失）、適當處理垃圾（果皮廚餘衛生紙全數帶下山）、保持自然原貌（不帶走一草一木一石）、減低用火衝擊（優先使用爐具）、尊重野生動植物（不餵食不干擾）、考量其他使用者（降低聲響、禮讓上坡行進者）。",
        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】\n1. 檢視甲組：高山與森林氣溫較低、微生物相與平地不同，香蕉皮與橘子皮往往數月至數年仍無法完全分解，濃湯油脂鹽分更會污染土壤水源並吸引野生動物翻找垃圾、喪失自然覓食能力，違反第 3 與第 6 原則。\n2. 檢視乙組：未經許可採摘野生蘭花、撿拾礦石違反第 4 原則「保持自然原貌」，餵食松鼠會改變動物習性並傳播疾病，違反第 6 原則。\n3. 檢視丙組：走既有步道不切捷徑（第 2 原則）、用瓦斯爐取代生營火（第 5 原則）、廚餘果皮衛生紙全數密封帶走（第 3 原則），完全符合 LNT 規範。\n4. 檢視丁組：大聲播放音樂破壞山林寧靜並干擾鳥類獸類棲息，且山徑窄路會車時，上坡山友重心前傾、視野較受限且體能負荷大，下坡者應主動於安全寬敞處停下禮讓上坡者先行，違反第 7 原則。故正確選項為 (C)。",
        "【第 4 步：易錯陷阱 · 混淆選項逐項剖析與迷思防線】\n• 選項 (A) 錯誤：這是最常見的「假環保迷思」！外來果皮不僅可能攜帶外來病菌種子，更會誘使台灣獼猴、黃喉貂與鼠類聚集步道旁乞食甚至攻擊山友。\n• 選項 (B) 錯誤：若每位遊客都以做紀念或觀察為由帶走一顆石頭、一朵花，熱門步道自然景觀將迅速浩劫；觀察應以攝影或素描紀錄取代採集。\n• 選項 (D) 錯誤：擴音音樂是山林噪音公害（防熊防蛇應靠正常交談腳步聲或打草驚蛇而非重低音舞曲），且山徑禮儀為「下坡禮讓上坡、輕裝禮讓重裝」。",
