      "stem": "童軍露營與防災演練中，小隊需依不同受力需求選用正確繩結以確保安全。下表列出四項現場實務任務：\n• 任務一（急救包紮收尾）：使用三角巾包紮傷患前臂後，需將兩端「粗細與材質完全相同」的布角打結固定，要求結形扁平不壓迫傷口且事後容易拆解。\n• 任務二（營柱工程起結）：搭建先鋒工程餐桌架時，需將麻繩起始端緊密纏繞固定在圓木營柱上，作為編紮工程的起結與收結。\n• 任務三（外帳張力調節）：帳篷營釘釘妥後，需在營繩末端打出可自由滑動「調整營繩長短與鬆緊度」、受風拉扯時又能自動止滑鎖緊的繩結。\n• 任務四（救援固定繩圈）：演練拖拉重物與救援受困者時，需打出一個「受力拉扯後繩圈大小固定不收縮勒緊、絕不滑脫，且卸力後仍易解開」的安全繩圈。\n請問任務一至任務四依序應選用下列哪一組童軍繩結？",
