      "stem": "學校輔導室舉辦七年級「校園社團與生涯類型探索週」，觀察並記錄了小宇、小晴、小柔、小軒四位同學最投入且展現熱忱的日常活動表現：\n• 小宇：在生活科技教室操作線鋸機、組裝太陽能齒輪車與協助總務處修繕鬆動的課桌椅時最專注，喜歡具體工具與動手實物操作勝過抽象文字討論。\n• 小晴：在科展社團熱衷設計對照實驗、推導數學規律並追根究柢查閱文獻，喜歡獨立邏輯思考與探索自然現象背後的成因。\n• 小柔：擔任班級愛心輔導股長與資源班伴讀小志工，擅長敏銳察覺同學低落情緒、溫暖傾聽煩惱並耐心教導同學解題，樂於團隊合作與助人。\n• 小軒：擔任班級總務股長與圖書室小義工，擅長將班費收支發票逐筆分類登錄試算表、依索書號精確歸位書籍並建立器材借還清冊，做事謹慎有條理。\n依據心理學家何倫（John Holland）提出的「六大生涯興趣類型（RIASEC）」，四位同學展現的主要傾向依序為何？",
