        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱時間規劃與目標管理（輔Bb-IV-2、1b-IV-1）：\n• **S（Specific 具體明確）**：指明具體科目單元、時段與執行動作。\n• **M（Measurable 可量化檢核）**：有明確題數、個數與正確率百分比可客觀驗收。\n• **A（Achievable 可達成）**：符合個人現有程度與健康睡眠負荷，可穩定持續執行。\n• **R（Relevant 具相關性）**：執行行動與欲提升之目標直接相關。\n• **T（Time-bound 明確時限）**：訂有總期限（3 週）與固定執行頻率時段。\n• **時間四象限**：提前 3 週固定排入晚間專注時段並關手機通知，正屬於投資「重要但不緊急」黃金象限。",
